input.new_string:
/** 清理对象池：移除距离过远且已失效的对象，防止内存无限增长 */
function cleanupPool(pool, maxSize) {
  let writeIdx = 0;
  for (let i = 0; i < pool.length; i++) {
    const obj = pool[i];
    if (obj.active || obj.dist > -600) {
      pool[writeIdx++] = obj;
    }
  }
  pool.length = writeIdx;
  // 安全阀：超过最大数量时裁剪最老的
  if (pool.length > maxSize) {
    const excess = pool.length - maxSize;
    pool.splice(0, excess);
  }
}

/** 统一的粒子爆发效果 */
function burstParticles(x, y, count, spreadX, spreadY, vRange, lifeRange, colors) {
  for (let i = 0; i < count; i++) {
    const p = poolGet(G.particles, () => createParticle(0,0,0,0,0,'#fff'));
    p.x = x + (Math.random() - 0.5) * spreadX;
    p.y = y + (Math.random() - 0.5) * spreadY;
    p.vx = (Math.random() - 0.5) * vRange;
    p.vy = (Math.random() - 0.5) * vRange;
    p.life = randInt(lifeRange[0], lifeRange[1]);
    p.maxLife = p.life;
    p.color = randChoice(colors);
    p.size = randInt(2, 5);
  }
}

