369	function resize() {
370	  const container = document.getElementById('game-container');
371	  const rect = container.getBoundingClientRect();
372	  const dpr = Math.min(window.devicePixelRatio || 1, 2); // 限制像素比
373	  G.W = rect.width;
374	  G.H = rect.height;
375	  G.canvas.width = G.W * dpr;
376	  G.canvas.height = G.H * dpr;
377	  G.canvas.style.width = G.W + 'px';
378	  G.canvas.style.height = G.H + 'px';
379	  G.ctx.setTransform(1, 0, 0, 1, 0, 0);
380	  G.ctx.scale(dpr, dpr);
381	
382	  /* 重新计算透视参数 */
383	  G.vanishX = G.W * 0.5;
384	  G.vanishY = G.H * 0.28;
385	  G.groundY = G.H * 0.88;
386	  G.laneSpread = G.W * 0.18;
387	
388	  /* 预渲染需要 resize */
389	  preRenderAssets();
390	}
391	
392	/* =========================== 预渲染资源 =========================== */
393	function preRenderAssets() {
394	  /* --- 天空渐变背景 --- */
395	  const skyCanvas = document.createElement('canvas');
396	  skyCanvas.width = G.W;
397	  skyCanvas.height = G.H;
398	  const skyCtx = skyCanvas.getContext('2d');
399	  const grad = skyCtx.createLinearGradient(0, 0, 0, G.vanishY + 40);
400	  grad.addColorStop(0, '#1a1a4e');
401	  grad.addColorStop(0.5, '#2d4a8e');
402	  grad.addColorStop(1, '#5ba3d9');
403	  skyCtx.fillStyle = grad;
404	  skyCtx.fillRect(0, 0, G.W, G.H);
405	  /* 云层 */
406	  skyCtx.fillStyle = 'rgba(255,255,255,0.08)';
407	  for (let ci = 0; ci < 8; ci++) {
408	    const cx = Math.random() * G.W;
409	    const cy = Math.random() * G.vanishY * 0.7;
410	    const cw = 60 + Math.random() * 120;
411	    skyCtx.beginPath();
412	    skyCtx.ellipse(cx, cy, cw, 12 + Math.random() * 10, 0, 0, Math.PI * 2);
413	    skyCtx.fill();
414	    skyCtx.beginPath();
415	    skyCtx.ellipse(cx + cw*0.3, cy - 8, cw*0.6, 10 + Math.random() * 8, 0, 0, Math.PI * 2);
416	    skyCtx.fill();
417	  }
418	  G.offscreen.sky = skyCanvas;
419	
420	  /* --- 城市天际线（远景） --- */
421	  const cityCanvas = document.createElement('canvas');
422	  cityCanvas.width = G.W * 3; // 宽于屏幕用于视差滚动
423	  cityCanvas.height = G.H * 0.25;
424	  const cityCtx = cityCanvas.getContext('2d');
425	  /* 建筑剪影 */
426	  cityCtx.fillStyle = '#1a1a3e';
427	  const buildings = [];
428	  let bx = 0;
429	  while (bx < cityCanvas.width) {
430	    const bw = randInt(30, 100);
431	    const bh = randInt(40, cityCanvas.height * 0.85);
432	    buildings.push({ x: bx, w: bw, h: bh });
433	    bx += bw + randInt(5, 20);
434	  }
435	  buildings.forEach(b => {
436	    cityCtx.fillRect(b.x, cityCanvas.height - b.h, b.w, b.h);
437	    /* 远处涂鸦（简化色块） */
438	    if (Math.random() < 0.2 && b.w > 50) {
439	      const tagColors = ['#ff3366','#ff6600','#33ff66','#33ccff','#ff33cc'];
440	      cityCtx.fillStyle = tagColors[Math.floor(Math.random() * tagColors.length)];
441	      cityCtx.fillRect(b.x + 8, cityCanvas.height - b.h + 10, b.w - 16, 8);
442	    }
443	    /* 窗户光点 */
444	    cityCtx.fillStyle = 'rgba(255,220,150,0.3)';
445	    for (let wy = cityCanvas.height - b.h + 8; wy < cityCanvas.height - 8; wy += 12) {
446	      for (let wx = b.x + 6; wx < b.x + b.w - 6; wx += 10) {
447	        if (Math.random() < 0.4) cityCtx.fillRect(wx, wy, 3, 3);
448	      }
449	    }
450	    cityCtx.fillStyle = '#1a1a3e';
451	  });
452	  G.offscreen.city = cityCanvas;
453	
454	  /* --- 近景建筑（更大、暖色调） --- */
455	  const nearCanvas = document.createElement('canvas');
456	  nearCanvas.width = G.W * 2;
457	  nearCanvas.height = G.H * 0.35;
458	  const nearCtx = nearCanvas.getContext('2d');
459	  nearCtx.fillStyle = '#2a1a0a';
460	  let nx = 0;
461	  while (nx < nearCanvas.width) {
462	    const nw = randInt(60, 160);
463	    const nh = randInt(80, nearCanvas.height * 0.9);
464	    nearCtx.fillRect(nx, nearCanvas.height - nh, nw, nh);
465	    /* 更大更亮的窗户 */
466	    nearCtx.fillStyle = 'rgba(255,200,100,0.2)';
467	    for (let wy = nearCanvas.height - nh + 12; wy < nearCanvas.height - 10; wy += 16) {
468	      for (let wx = nx + 10; wx < nx + nw - 10; wx += 14) {
469	        if (Math.random() < 0.35) nearCtx.fillRect(wx, wy, 5, 6);
470	      }
471	    }
472	    /* 随机涂鸦标签（30%几率） */
473	    if (Math.random() < 0.3) {
474	      const tagW = randInt(30, nw - 10);
475	      const tagH = randInt(20, Math.min(60, nh - 20));
476	      const tagX = nx + randInt(5, nw - tagW - 5);
477	      const tagY = nearCanvas.height - nh + randInt(10, nh - tagH - 10);
478	      drawGraffitiTag(nearCtx, tagX, tagY, tagW, tagH);
479	    }
480	    nearCtx.fillStyle = '#2a1a0a';
481	    nx += nw + randInt(8, 30);
482	  }
483	  G.offscreen.nearCity = nearCanvas;
484	
485	  /* --- 玩家角色精灵表 --- */
486	  /* --- 地面 + 轨道（静态，预渲染） --- */
487	  preRenderGroundAndTracks();
488	
489	  preRenderPlayerSprites();
490	
491	  /* --- 障碍物图块 --- */
492	  G.offscreen.obstacles = {};
493	  /* 低障碍（横杆） */
494	  let oc = document.createElement('canvas'); oc.width=60; oc.height=20;
495	  drawObstacleSprite(oc.getContext('2d'), OBS_LOW, oc.width, oc.height);
496	  G.offscreen.obstacles[OBS_LOW] = oc;
497	  /* 中障碍（信号灯箱） */
498	  oc = document.createElement('canvas'); oc.width=40; oc.height=55;
499	  drawObstacleSprite(oc.getContext('2d'), OBS_MID, oc.width, oc.height);
500	  G.offscreen.obstacles[OBS_MID] = oc;
501	  /* 高障碍（信号塔） */
502	  oc = document.createElement('canvas'); oc.width=50; oc.height=120;
503	  drawObstacleSprite(oc.getContext('2d'), OBS_HIGH, oc.width, oc.height);
504	  G.offscreen.obstacles[OBS_HIGH] = oc;
505	
506	  /* --- 金币 --- */
507	  const coinCanvas = document.createElement('canvas');
508	  coinCanvas.width = 32; coinCanvas.height = 32;
509	  drawCoinSprite(coinCanvas.getContext('2d'), coinCanvas.width, coinCanvas.height);
510	  G.offscreen.coin = coinCanvas;
511	
512	  /* --- 粒子 --- */
513	  const partCanvas = document.createElement('canvas');
514	  partCanvas.width = 8; partCanvas.height = 8;
515	  const partCtx = partCanvas.getContext('2d');
516	  partCtx.fillStyle = '#fff';
517	  partCtx.beginPath(); partCtx.arc(4,4,4,0,Math.PI*2); partCtx.fill();
518	  G.offscreen.particle = partCanvas;
519	}
