function spawnCoinRow() {
  /* 单条轨道，几个金币 */
  const lane = randInt(0, 2);
  for (let d = G.maxDist - 20; d < G.maxDist + 20; d += 60) {
    const c = poolGet(G.coins, () => createCoin(0, 0));
    c.lane = lane;
    c.dist = d + Math.random() * 10;
    c.collected = false;
  }
}

function spawnPowerup() {
  const lane = randInt(0, 2);
  const type = randChoice([PUP_MAGNET, PUP_SHIELD, PUP_2X]);
  const pu = poolGet(G.powerups, () => createPowerup(0, PUP_MAGNET, 0));
  pu.lane = lane;
  pu.type = type;
  pu.dist = G.maxDist + randInt(0, 50);
  pu.collected = false;
}


function applyPowerup(p, type) {
  if (type === PUP_SHIELD) {
    p.hasShield = true;
  } else {
    p.activePowerup = type;
    p.powerupTimer = POWERUP_DURATION;
    if (type === PUP_2X) p.scoreMultiplier = 2;
  }
}
/** 清理对象池：移除距离过远且已失效的对象，防止内存无限增长 */
function cleanupPool(pool, maxSize) {
  let writeIdx = 0;
  for (let i = 0; i < pool.length; i++) {
    const obj = pool[i];
    if (obj.active || obj.dist > -600) {
      pool[writeIdx++] = obj;
    }
  }
  pool.length = writeIdx;
  // 安全阀：超过最大数量时裁剪最老的
  if (pool.length > maxSize) {
    const excess = pool.length - maxSize;
    pool.splice(0, excess);
  }
}

/** 统一的粒子爆发效果 */
function burstParticles(x, y, count, spreadX, spreadY, vRange, lifeRange, colors) {
  for (let i = 0; i < count; i++) {
    const p = poolGet(G.particles, () => createParticle(0,0,0,0,0,'#fff'));
    p.x = x + (Math.random() - 0.5) * spreadX;
    p.y = y + (Math.random() - 0.5) * spreadY;
    p.vx = (Math.random() - 0.5) * vRange;
    p.vy = (Math.random() - 0.5) * vRange;
    p.life = randInt(lifeRange[0], lifeRange[1]);
    p.maxLife = p.life;
    p.color = randChoice(colors);
    p.size = randInt(2, 5);
  }
}

/* =========================== 渲染 =========================== */
function render() {
  const ctx = G.ctx;
  ctx.clearRect(0, 0, G.W, G.H);

  /* 屏幕震动 */
  ctx.save();
  if (G.shakeDuration > 0) {
    ctx.translate(
      (Math.random() - 0.5) * G.shakeX * 2,
      (Math.random() - 0.5) * G.shakeY * 2
    );
  }

  /* --- 天空 --- */
  ctx.drawImage(G.offscreen.sky, 0, 0);

  /* --- 远城市场景视差 --- */
  const cityOffset = (G.distance * 0.15) % (G.W * 3);
  ctx.drawImage(G.offscreen.city, -cityOffset, G.vanishY - 30, G.W, G.H*0.25, 0, G.vanishY - 30, G.W, G.H*0.25);

