      if (sameLane(obs)) {
        if (obs.type === OBS_LOW && p.state === STATE_SLIDE) continue;
        if (obs.type === OBS_MID && p.state === STATE_JUMP) continue;
        hurtPlayer(1);
      }
    }
    if (!obs.passed && obs.dist < COLLISION_FAR && sameLane(obs) && p.celebrateTimer <= 0) {
      obs.passed = true;
      if (obs.type === OBS_MID && p.state === STATE_JUMP) {
        p.celebrateType = 'lookback';
        p.celebrateTimer = CELEBRATE_LOOKBACK;
      } else if (obs.type === OBS_LOW && p.state === STATE_SLIDE) {
        p.celebrateType = 'kick';
        p.celebrateTimer = CELEBRATE_KICK;
      }
    }
    if (obs.dist < COLLISION_FAR) obs.passed = true;
  }
}

function updateCoins(p) {
  for (let i = 0; i < G.coins.length; i++) {
    const coin = G.coins[i];
    if (!coin.active) continue;
    coin.dist -= G.speed;
    if (coin.dist < -400) { coin.active = false; continue; }
    if (!coin.collected && coin.dist < COLLECT_NEAR && coin.dist > COLLECT_FAR && Math.abs(coin.lane - p.lane) < COLLECT_LANE_RANGE) {
      coin.collected = true;
      coin.sparkTimer = 10;
      G.coinScore += COIN_SCORE * G.player.scoreMultiplier;
      sfxCoin();
      const s = worldToScreen(coin.dist);
      const sx = laneX(coin.lane, coin.dist);
      burstParticles(sx, s.y, 6, 20, 20, 4, [10, 25], ['#ffdd44','#ffaa00','#ffe680','#fff']);
    }
  }
}

function updateParticles() {
  for (let i = 0; i < G.particles.length; i++) {
    const pt = G.particles[i];
    if (!pt.active) continue;
    pt.x += pt.vx;
    pt.y += pt.vy;
    pt.life--;
    if (pt.life <= 0) pt.active = false;
  }
}

function updateSpawning() {
  G.spawnTimer++;
  const interval = G.spawnInterval / (G.speed / BASE_SPEED);
  if (G.spawnTimer >= interval) {
    G.spawnTimer = 0;
    spawnObstacle();
  }
  G.coinTimer++;
  if (G.coinTimer > COIN_SPAWN_BASE + Math.random() * COIN_SPAWN_RAND) {
    G.coinTimer = 0;
    spawnCoinRow();
  }
  if (!G.powerupSpawnTimer) G.powerupSpawnTimer = POWERUP_SPAWN_BASE + Math.random() * POWERUP_SPAWN_RAND;
  G.powerupSpawnTimer--;
  if (G.powerupSpawnTimer <= 0) {
    G.powerupSpawnTimer = POWERUP_SPAWN_BASE + Math.random() * POWERUP_SPAWN_RAND;
    if (G.powerups.filter(pu => pu.active).length < MAX_POWERUPS) spawnPowerup();
  }
}

function updatePowerups(p) {
  for (let i = 0; i < G.powerups.length; i++) {
    const pu = G.powerups[i];
    if (!pu.active) continue;
    pu.dist -= G.speed;
    if (pu.dist < -400) { pu.active = false; continue; }
    pu.floatPhase += 0.05;
    if (!pu.collected && pu.dist < COLLECT_NEAR && pu.dist > COLLECT_FAR && Math.abs(pu.lane - p.lane) < COLLECT_LANE_RANGE) {
      pu.collected = true;
      pu.sparkTimer = 12;
      sfxPowerup();
      applyPowerup(p, pu.type);
      const s = worldToScreen(pu.dist);
      const sx = laneX(pu.lane, pu.dist);
      const puColor = pu.type === PUP_MAGNET ? '#ff44ff' : pu.type === PUP_SHIELD ? '#44aaff' : '#ffdd00';
      burstParticles(sx, s.y, 10, 30, 30, 6, [15, 35], [puColor, '#fff', puColor]);
    }
  }
  if (p.powerupTimer > 0) {
    p.powerupTimer--;
    if (p.powerupTimer <= 0) {
      p.activePowerup = null;
      p.scoreMultiplier = 1;
    }
  }
  if (p.activePowerup === PUP_MAGNET) {
    for (let i = 0; i < G.coins.length; i++) {
      const c = G.coins[i];
      if (!c.active || c.collected) continue;
      if (Math.abs(c.lane - p.lane) < MAGNET_RANGE && c.dist < MAGNET_DIST_NEAR && c.dist > MAGNET_DIST_FAR) {
        c.lane += (p.lane - c.lane) * MAGNET_PULL;
        c.dist -= G.speed * MAGNET_SPEED_BOOST;
      }
    }
  }
}

function updateFinalize(p) {
  cleanupPool(G.obstacles, 30);
  cleanupPool(G.coins, 40);
  cleanupPool(G.particles, 80);
  cleanupPool(G.powerups, 5);
  p.y = G.groundY;
  if (p.state === STATE_JUMP) {
    p.y = G.groundY - JUMP_PEAK_HEIGHT - (p.stateTimer / JUMP_DURATION) * JUMP_CURVE;
  }
  p.scale = 1.0;
  p.x = laneX(p.lane, 0);
  if (G.frameCount % DUST_INTERVAL === 0 && G.state === 'playing') {
    burstParticles(p.x, G.groundY + 12, 2, 20, 4, 0.8, [8, 18], ['rgba(180,160,140,0.5)']);
  }
}

