/* =========================== 分数弹出文字 =========================== */
function spawnPopup(x, y, text, color) {
  G.popups.push({ x, y, text, color, life: 40, vy: -1.5, alpha: 1 });
}

function updatePopups() {
  for (let i = G.popups.length - 1; i >= 0; i--) {
    const p = G.popups[i];
    p.y += p.vy;
    p.life--;
    p.alpha = Math.min(1, p.life / 20);
    if (p.life <= 0) G.popups.splice(i, 1);
  }
}

function renderPopups(ctx) {
  for (let i = 0; i < G.popups.length; i++) {
    const p = G.popups[i];
    ctx.globalAlpha = p.alpha;
    ctx.fillStyle = p.color;
    ctx.font = 'bold 16px "Segoe UI","PingFang SC",sans-serif';
    ctx.textAlign = 'center';
    ctx.shadowColor = 'rgba(0,0,0,0.5)';
    ctx.shadowBlur = 3;
    ctx.fillText(p.text, p.x, p.y);
    ctx.shadowBlur = 0;
  }
  ctx.globalAlpha = 1;
}

